function toggleNav(){document.getElementById("nav")?.classList.toggle("open")}function toggleSearch(){const p=document.getElementById("searchPanel");p?.classList.toggle("open");if(p?.classList.contains("open"))document.getElementById("searchInput")?.focus()}function filterStories(){const q=(document.getElementById("searchInput")?.value||"").toLowerCase().trim();document.querySelectorAll(".story-grid .story").forEach(c=>c.style.display=(!q||c.innerText.toLowerCase().includes(q))?"":"none")}function subscribe(e){e.preventDefault();alert("Suscripción preparada para conectar con tu proveedor de newsletter.");e.target.reset()}if("serviceWorker"in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("/journal/sw.js").catch(()=>{}));